pub fn pack_to(&mut self, minimum_capacity: usize) -> HashMap<Index<T>, Index<T>> {
    if minimum_capacity < self.length {
        panic!("minimum capacity must be greater than or equal to the current length");
    }

    let mut map = HashMap::new();
    let mut new_entries = Vec::with_capacity(minimum_capacity);
    let mut current_index = self.head;

    while let Some(index) = current_index {
        if let Some(entry) = self.entries[index.get()].occupied_ref() {
            let new_index = new_entries.len();
            new_entries.push(entry.clone());
            map.insert(index, Index::new(new_index));
            current_index = entry.next;
        } else {
            break;
        }
    }

    self.entries = new_entries.into_iter().map(Entry::Occupied).collect();
    self.generation += 1;
    self.head = Some(NonMaxUsize::new(0).unwrap());
    self.tail = Some(NonMaxUsize::new(self.entries.len() - 1).unwrap());
    self.vacant_head = None;

    map
}

